-- =====================================================================
--  Prime Script — Contenu prêt à l'emploi (9/12) : Appels à l'action (service × étape)
--
--  Ce fichier s'importe avec les autres fichiers de database/content/ :
--      php tools/import-content.php
--  (ou, en MySQL : mysql -u ... prime_script < database/content/content.sql
--   si ce fichier a été concaténé dans content.sql).
--
--  Format d'une ligne de contenu (JSON, une ligne par enregistrement) :
--    {"code": "...", "type": "...", "sector": "...", "stage": "...",
--     "service": "...", "title": "...", "position": 10, "content": "<p>…</p>"}
--
--    code     identifiant stable du bloc (réimport = mise à jour, jamais de doublon)
--    type     presentation | accroche | barrage | repondeur | decouverte |
--             argumentaire | preuve | tarif | appel_action | conclusion
--    sector   slug du secteur (architectes, artisans-btp, restauration, services-b2b)
--    stage    slug de l'étape (premier-appel, relance, closing)
--    service  slug du service (site-web, application, automatisation-ia, chatbot-ia)
--    content  HTML simple : <p>, <ul>, <li>, <strong>, <em>
--
--  Convention d'écriture : le texte à dire est en clair, l'aide au commercial
--  est sur une ligne « Conseil : … » en italique (<p><em>Conseil : …</em></p>).
-- =====================================================================

SET NAMES utf8mb4;

{"code": "cta-site-web-premier-appel", "type": "appel_action", "stage": "premier-appel", "title": "Site web — appeler à l'action (premier appel)", "content": "<ul><li>Je vous propose une chose simple : l'audit gratuit de votre site actuel. Une note sur 100, ce qui bloque, et un PDF à garder.<br><em>Conseil : c'est gratuit et sans engagement. Dites-le avant que le client ne le demande.</em></li><li>Je peux aussi vous envoyer le simulateur de budget : vous choisissez les pages, il donne un ordre de prix tout de suite.<br><em>Conseil : envoyez le lien pendant l'appel, pas « plus tard ». Le client l'ouvre souvent aussitôt.</em></li><li>Ou quinze minutes en visio cette semaine, pour regarder ensemble ce qui manque à votre site.<br><em>Conseil : proposez deux créneaux précis, jamais « quand vous voulez ».</em></li></ul><br><em>Conseil : Prenez l'engagement le plus petit possible. Un audit gratuit ouvre plus de portes qu'un rendez-vous d'une heure.</em>", "service": "site-web"}
{"code": "cta-site-web-relance", "type": "appel_action", "stage": "relance", "title": "Site web — appeler à l'action (relance)", "content": "<ul><li>On reprend là où on s'était arrêtés : vous alliez regarder le devis et me dire ce qui coince.<br><em>Conseil : rappelez la date du dernier échange, ça prouve que vous suivez le dossier.</em></li><li>Si le prix est le sujet, je peux découper en deux étapes : la page d'accueil d'abord, le reste ensuite.<br><em>Conseil : découper réduit le risque perçu. C'est souvent ce qui débloque.</em></li><li>Dites-moi une date : je vous rappelle jeudi à 11 h, ou mardi à 15 h ?<br><em>Conseil : après avoir proposé deux créneaux, écrivez la date dans la note de l'appel.</em></li></ul><br><em>Conseil : En relance, le but n'est pas de convaincre à nouveau : c'est de fixer la prochaine étape, datée.</em>", "service": "site-web"}
{"code": "cta-site-web-closing", "type": "appel_action", "stage": "closing", "title": "Site web — appeler à l'action (closing)", "content": "<ul><li>Je récapitule : un site professionnel de six pages, la mise en ligne, et le formulaire de contact. Prix du devis, sans surprise.<br><em>Conseil : trois éléments, pas six. Un récapitulatif trop long rouvre le débat.</em></li><li>Il ne reste que votre accord. Je vous envoie le devis à signer maintenant, ou vous préférez demain matin ?<br><em>Conseil : deux options, aucune n'étant « plus tard ». C'est ce qui fait avancer.</em></li></ul><br><em>Conseil : Le closing ne sert pas à re-vendre. Il sert à retirer le dernier obstacle et à fixer la date.</em>", "service": "site-web"}
{"code": "cta-application-premier-appel", "type": "appel_action", "stage": "premier-appel", "title": "Application — appeler à l'action (premier appel)", "content": "<ul><li>Avant de parler d'application, je vous propose un appel de quinze minutes pour comprendre comment vous travaillez aujourd'hui.<br><em>Conseil : on ne chiffre pas une application sans avoir vu le processus. Dites-le.</em></li><li>Si vous préférez, je vous envoie le simulateur : vous choisissez les écrans, il donne un budget de départ immédiat.<br><em>Conseil : le simulateur dédramatise le prix avant même le premier rendez-vous.</em></li><li>Et si le sujet est plus simple, l'audit gratuit de votre site reste possible : c'est souvent par là qu'on commence.<br><em>Conseil : proposer plusieurs portes d'entrée évite le « tout ou rien ».</em></li></ul><br><em>Conseil : Une application fait peur par son budget. Le premier pas doit être petit : un échange, un simulateur, un audit.</em>", "service": "application"}
{"code": "cta-application-relance", "type": "appel_action", "stage": "relance", "title": "Application — appeler à l'action (relance)", "content": "<ul><li>On avait parlé de remplacer vos tableurs. Est-ce que le besoin est toujours là, ou la période a changé ?<br><em>Conseil : poser la question du besoin, pas du projet. Un besoin qui reste est un projet qui revient.</em></li><li>Je peux vous proposer une première version limitée à votre module le plus douloureux, pour démarrer plus petit.<br><em>Conseil : le prototype démarre à 2 900 € HT. C'est un vrai point d'entrée, pas un argument.</em></li><li>On se cale vingt minutes avec la personne qui utilise l'outil tous les jours ?<br><em>Conseil : impliquer un utilisateur, pas seulement le dirigeant. C'est lui qui validera l'outil.</em></li></ul><br><em>Conseil : En relance d'application, le frein est presque toujours le budget. Découper est la meilleure réponse.</em>", "service": "application"}
{"code": "cta-application-closing", "type": "appel_action", "stage": "closing", "title": "Application — appeler à l'action (closing)", "content": "<ul><li>Le prototype est validé, le périmètre est écrit. On peut démarrer le développement lundi.<br><em>Conseil : un démarrage daté vaut mieux qu'un « on y va ».</em></li><li>Vous validez chaque étape avant la suivante : rien ne vous engage au-delà de ce que vous avez vu.<br><em>Conseil : c'est la phrase qui rassure le plus en closing. Gardez-la pour la fin.</em></li><li>Je vous envoie le devis à signer. Le paiement peut se faire en trois fois, sans frais supplémentaires.<br><em>Conseil : ne dites pas « sans frais » si ce n'est pas écrit dans le devis. Vérifiez avant.</em></li></ul><br><em>Conseil : Au closing, rappelez la livraison par étapes. C'est ce qui fait signer les projets à plusieurs milliers d'euros.</em>", "service": "application"}
{"code": "cta-automatisation-ia-premier-appel", "type": "appel_action", "stage": "premier-appel", "title": "Automatisation — appeler à l'action (premier appel)", "content": "<ul><li>Je vous propose l'audit du temps perdu : on liste ensemble les tâches qui reviennent, et je vous dis ce qui peut disparaître.<br><em>Conseil : c'est un audit, pas un devis déguisé. Présentez-le comme tel.</em></li><li>Si vous préférez voir avant, l'automatisation démarre à 1 500 € HT : vous saurez tout de suite dans quelle fourchette vous êtes.<br><em>Conseil : annoncer le prix tôt évite une conversation de vingt minutes pour rien.</em></li><li>On peut faire ça par téléphone en vingt minutes, ou en visio si vous voulez montrer vos outils.<br><em>Conseil : la visio est souvent plus efficace, le client montre son écran.</em></li></ul><br><em>Conseil : L'automatisation se vend par l'audit, pas par la démonstration technique.</em>", "service": "automatisation-ia"}
{"code": "cta-automatisation-ia-relance", "type": "appel_action", "stage": "relance", "title": "Automatisation — appeler à l'action (relance)", "content": "<ul><li>Vous m'aviez parlé des relances de devis qui n'étaient jamais faites. On peut commencer par cette seule tâche.<br><em>Conseil : reprendre une seule tâche concrète rend le projet tangible.</em></li><li>Le devis pour cette partie serait beaucoup plus petit que celui du projet complet.<br><em>Conseil : annoncer un devis plus petit est une bonne nouvelle. Dites-le franchement.</em></li><li>On se donne vingt minutes jeudi pour lister les trois tâches à automatiser en premier ?<br><em>Conseil : trois tâches, pas dix. Un premier lot trop large ne se termine jamais.</em></li></ul><br><em>Conseil : En relance, réduisez le périmètre. Une automatisation livrée vaut mieux qu'un projet reporté.</em>", "service": "automatisation-ia"}
{"code": "cta-automatisation-ia-closing", "type": "appel_action", "stage": "closing", "title": "Automatisation — appeler à l'action (closing)", "content": "<ul><li>On démarre par les relances de devis. Mise en place en deux à trois semaines, puis on regarde ce qui reste.<br><em>Conseil : donner une durée, même indicative, rassure plus qu'un « rapidement ».</em></li><li>Vous gardez le contrôle : chaque message part après votre validation, pendant les premières semaines.<br><em>Conseil : proposer un contrôle humain au démarrage réduit nettement la peur.</em></li><li>Je vous envoie le devis à signer aujourd'hui, et on planifie l'atelier de lancement.<br><em>Conseil : un atelier de lancement daté transforme un devis en projet.</em></li></ul><br><em>Conseil : Le closing d'automatisation se joue sur la confiance, pas sur la technique. Restez concret.</em>", "service": "automatisation-ia"}
{"code": "cta-chatbot-ia-premier-appel", "type": "appel_action", "stage": "premier-appel", "title": "Chatbot — appeler à l'action (premier appel)", "content": "<ul><li>Le plus simple : testez la démo gratuite sur notre site. Elle existe pour votre secteur, sans inscription, en deux minutes.<br><em>Conseil : c'est l'argument le plus fort du catalogue. Proposez-le systématiquement.</em></li><li>Si la démo vous parle, on regarde ensemble les questions qui reviennent chez vous, et on construit l'assistant dessus.<br><em>Conseil : trois ou quatre questions suffisent pour un premier assistant utile.</em></li><li>En attendant, je peux vous envoyer le lien par mail tout de suite, avec les tarifs de départ.<br><em>Conseil : demandez l'adresse mail pendant l'appel. Après, le taux de réponse chute.</em></li></ul><br><em>Conseil : La démo fait le travail à votre place. Ne la remplacez pas par une explication technique.</em>", "service": "chatbot-ia"}
{"code": "cta-chatbot-ia-relance", "type": "appel_action", "stage": "relance", "title": "Chatbot — appeler à l'action (relance)", "content": "<ul><li>Avez-vous pu tester la démo ? Si oui, qu'est-ce qui vous a plu, et qu'est-ce qui vous a manqué ?<br><em>Conseil : les deux questions ensemble. La seconde est la plus utile.</em></li><li>Si l'assistant doit répondre sur vos documents, on passe au forfait connecté, mais on peut démarrer par les questions fréquentes.<br><em>Conseil : commencer petit, quitte à compléter dans trois mois.</em></li><li>On peut faire un test réel sur votre site pendant une semaine, sur une seule page. Ça vous irait ?<br><em>Conseil : ne promettez pas de test gratuit si ce n'est pas validé en interne. Vérifiez avant de proposer.</em></li></ul><br><em>Conseil : En relance de chatbot, repartez de la démo. C'est ce dont le client se souvient.</em>", "service": "chatbot-ia"}
{"code": "cta-chatbot-ia-closing", "type": "appel_action", "stage": "closing", "title": "Chatbot — appeler à l'action (closing)", "content": "<ul><li>Le contenu de l'assistant est validé par vous, question par question. Il ne dira rien que vous n'ayez approuvé.<br><em>Conseil : c'est la phrase qui fait signer. Mettez-la avant le prix.</em></li><li>Mise en service en une à deux semaines pour le forfait de départ. On regarde les conversations ensemble la première semaine.<br><em>Conseil : proposer un suivi de la première semaine rassure beaucoup.</em></li><li>Je vous envoie le devis à signer. Vous voulez qu'on fixe la date de mise en ligne maintenant ?<br><em>Conseil : fixer la date avant l'envoi du devis accélère la signature.</em></li></ul><br><em>Conseil : Le closing de chatbot se joue sur la peur de l'erreur. Promettez le contrôle, pas la perfection.</em>", "service": "chatbot-ia"}
{"code": "cta-*-premier-appel", "type": "appel_action", "stage": "premier-appel", "title": "Appel à l'action — premier appel", "content": "<ul><li>Je vous propose une première étape simple, gratuite et sans engagement : l'audit de votre site, avec une note sur 100.<br><em>Conseil : une étape minuscule fait accepter beaucoup plus facilement la suivante.</em></li><li>Ou quinze minutes de visio pour regarder votre situation ensemble, sans rien vendre.<br><em>Conseil : « sans rien vendre » doit être vrai. C'est ce qui rend la phrase crédible.</em></li></ul><br><em>Conseil : Choisissez l'étape la plus petite possible. C'est elle qui crée le second appel.</em>"}
{"code": "cta-*-relance", "type": "appel_action", "stage": "relance", "title": "Appel à l'action — relance", "content": "<ul><li>On reprend là où on s'était arrêtés, et on fixe une date pour la suite.<br><em>Conseil : sans date, une relance est un appel perdu.</em></li><li>Jeudi à 11 h ou mardi à 15 h : qu'est-ce qui vous arrange le mieux ?<br><em>Conseil : deux créneaux, pas trois. Trois, c'est déjà une hésitation.</em></li></ul><br><em>Conseil : Une relance réussie se mesure au rendez-vous suivant, pas à la longueur de l'appel.</em>"}
{"code": "cta-*-closing", "type": "appel_action", "stage": "closing", "title": "Appel à l'action — closing", "content": "<ul><li>Je récapitule en trois phrases, et vous me dites si j'ai bon.<br><em>Conseil : le récapitulatif fait dire « oui » trois fois au client.</em></li><li>Il ne reste que la date de démarrage. On la fixe maintenant ?<br><em>Conseil : une date de démarrage est plus facile à accepter qu'un « accord de principe ».</em></li></ul><br><em>Conseil : Au closing, une seule question à la fois. Deux questions, plus de réponse.</em>"}
